65|export function classifyKeys(dir: string): StepKeys {
66|  const scenes = asRecord(readJson(join(dir, "scenes.json")));
67|  const analysis = asRecord(readJson(join(dir, "analysis.json")));
68|  const list = Array.isArray(scenes.scenes) ? (scenes.scenes as { id: unknown; ch: unknown; start_n: unknown; end_n: unknown; title: unknown; summary: unknown; characters: unknown }[]) : undefined;
