72|export function resplitKeys(dir: string): StepKeys {
73|  const analysis = asRecord(readJson(join(dir, "analysis.json")));
74|  const list = Array.isArray(analysis.scenes) ? (analysis.scenes as { id: unknown; start_n: unknown; end_n: unknown }[]) : undefined;
