79|  const analysis = asRecord(readJson(join(dir, "analysis.json")));
80|  const clusters = asRecord(readJson(join(dir, "music-clusters.json")));
81|  const list = Array.isArray(analysis.scenes) ? (analysis.scenes as { id: unknown; final: unknown }[]) : undefined;
