85|export type FreshStep = "segment" | "classify" | "resplit" | "cluster";
86|
87|const STEP_ORDER: FreshStep[] = ["segment", "classify", "resplit", "cluster"];
88|
89|const STEP_KEYS: Record<FreshStep, (dir: string) => StepKeys> = { segment: segmentKeys, classify: classifyKeys, resplit: resplitKeys, cluster: clusterKeys };
90|
91|export interface StepPlan {
92|  step: FreshStep;
93|  reuse: boolean;
94|  reason: string;
95|}
96|
97|// Plans the selected steps in pipeline order. Once a step would redo,
98|// every later step redoes too, since its input comes from that step.
99|export function planSteps(dir: string, steps: FreshStep[], force: boolean): StepPlan[] {
100|  const wanted = STEP_ORDER.filter((step) => steps.includes(step));
101|  const plans: StepPlan[] = [];
102|  let upstreamRedoes = false;
103|  for (const step of wanted) {
104|    if (upstreamRedoes) {
105|      plans.push({ step, reuse: false, reason: "upstream step redoes" });
106|      continue;
107|    }
108|    const keys = STEP_KEYS[step](dir);
109|    const decision = decide(force, keys.recorded, keys.current);
110|    if (!decision.reuse) upstreamRedoes = true;
111|    plans.push({ step, ...decision });
112|  }
113|  return plans;
